N1 = 'n = int(input())\na = list(map(int, input().split()))\n'
NX = 'n, x = map(int, input().split())\na = list(map(int, input().split()))\n'
NK = 'n, k = map(int, input().split())\na = list(map(int, input().split()))\n'

def g1(nlo, nhi, lo, hi):
    return 'r => { const n = olInt(r, %d, %d); return n + "\\n" + olArr(r, n, %d, %d).join(" "); }' % (nlo, nhi, lo, hi)

INP = {
    'ru': lambda nlo, nhi, lo, hi: f'В первой строке — целое число n ({nlo} ≤ n ≤ {nhi}). Во второй — n целых чисел через пробел, каждое от {lo} до {hi}.'.replace('-', '−'),
    'kz': lambda nlo, nhi, lo, hi: f'Бірінші жолда — бүтін сан n ({nlo} ≤ n ≤ {nhi}). Екінші жолда — бос орын арқылы n бүтін сан, әрқайсысы {lo} мен {hi} аралығында.'.replace('-', '−'),
}

def T(slot, vid, stars, name, text, out, hint, ref, samples, hidden, gen, inp=None, start=N1, rng=(1, 100, 1, 100)):
    if inp is None:
        inp = {L: INP[L](*rng) for L in ('ru', 'kz')}
    return dict(slot=slot, id=slot + str(vid), stars=stars, name=name, text=text, inp=inp, out=out, hint=hint,
                ref=start + ref, start=start, samples=samples, hidden=hidden, gen=gen)

